import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Kimi 对话与 Agent 术语表","description":"不教操作。把都叫 Kimi / Agent / Goal / Project 的东西拆开。","frontmatter":{"title":"Kimi 对话与 Agent 术语表","description":"不教操作。把都叫 Kimi / Agent / Goal / Project 的东西拆开。","domain":"product","tags":["chat"],"role":"glossary"},"headers":[],"relativePath":"zh/products/kimi/kimi-glossary.md","filePath":"zh/products/kimi/kimi-glossary.md","lastUpdated":1787110548000}'),d={name:"zh/products/kimi/kimi-glossary.md"};function i(n,t,s,l,m,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="kimi-对话与-agent-术语表" tabindex="-1">Kimi 对话与 Agent 术语表 <a class="header-anchor" href="#kimi-对话与-agent-术语表" aria-label="Permalink to &quot;Kimi 对话与 Agent 术语表&quot;">​</a></h1><p>不教操作。只回答「这个词在官方页上是什么、不是什么」。选产品面回 <a href="./">学习地图</a>。模型内部见 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>。</p><h2 id="都叫-kimi-的东西" tabindex="-1">都叫 Kimi 的东西 <a class="header-anchor" href="#都叫-kimi-的东西" aria-label="Permalink to &quot;都叫 Kimi 的东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>在哪</th></tr></thead><tbody><tr><td><strong>Kimi</strong></td><td>一站式 AI 工作台 / All-in-one agentic AI workspace</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td><strong>Kimi Agent</strong></td><td>端到端自主助手，K3 + 20+ 工具</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td><strong>Agent Swarm</strong></td><td>最多 300 个子 Agent 并行</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td><strong>Kimi Claw</strong></td><td>一键云端 OpenClaw，可接即时通讯渠道</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td><strong>Kimi Code</strong></td><td>终端与 IDE 编程助手</td><td><a href="/zh/products/kimi-code/">Kimi Code</a></td></tr><tr><td><strong>Kimi Work</strong></td><td>Mac/Windows 桌面知识工作 Agent（Work / Chat 双模式）</td><td><a href="https://www.kimi.com/products/kimi-work" target="_blank" rel="noreferrer">products/kimi-work</a></td></tr><tr><td><strong>Kimi WebBridge</strong></td><td>给 Agent 用的浏览器插件</td><td>产品页</td></tr><tr><td><strong>Kimi Platform</strong></td><td>官方模型 API</td><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td></tr><tr><td><strong>Kimi Business</strong></td><td>企业方案</td><td>帮助中心</td></tr><tr><td><strong>Kimi Plus</strong></td><td>插件页点名「Kimi Plus 对话」暂不支持插件</td><td><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td><strong>K2.6 / K3 / K3 Swarm</strong></td><td>工作台里的模型 / 模式开关</td><td>输入框上方模型切换</td></tr><tr><td><strong>Moonshot AI / 月之暗面</strong></td><td>公司</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td></tr></tbody></table><h2 id="agent-家族-三个调度面" tabindex="-1">Agent 家族：三个调度面 <a class="header-anchor" href="#agent-家族-三个调度面" aria-label="Permalink to &quot;Agent 家族：三个调度面&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>单 Agent</th><th>Agent Swarm</th><th>Claw 群聊</th></tr></thead><tbody><tr><td><strong>是什么</strong></td><td>一只助手拆任务、调工具</td><td>一只 orchestrator 拉最多 300 个子 Agent</td><td>多只 Claw + Kimi Conductor</td></tr><tr><td><strong>入口</strong></td><td><code>kimi.com/agent</code> 或 App 的 K3</td><td><code>kimi.com/agent-swarm</code> 或 K3 Swarm</td><td><code>kimi.com/bot</code> 里 Start Group Chat</td></tr><tr><td><strong>官方强调</strong></td><td>20+ 工具、Office / 网站交付</td><td>横向扩展、不必手写工作流</td><td>跨人、跨设备、跨权限边界</td></tr><tr><td><strong>不是</strong></td><td>不是 Kimi Code</td><td>不是「把 Claw 开 300 个」</td><td>不是 Swarm 的另一个名字</td></tr></tbody></table><p><strong>OpenClaw ≠ Kimi Claw。</strong> OpenClaw 是可自建的助手；Kimi Claw 是 Kimi 帮你部署或链上它的产品面。群聊里还可以带自己的 OpenClaw 当 Worker。</p><p><strong>OK Computer</strong> 是 2025-09-26 上线的早期 Agent 模式名称（Agent 时间线）。现在帮助中心主推 Kimi Agent / K3。</p><h2 id="goal-容易踩的坑" tabindex="-1">Goal 容易踩的坑 <a class="header-anchor" href="#goal-容易踩的坑" aria-label="Permalink to &quot;Goal 容易踩的坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说法</th><th>官方出现位置</th><th>不是</th></tr></thead><tbody><tr><td>Goal / 目标模式</td><td>会员表（Allegretto+）；项目对话可 use Goal</td><td>不是全站免费开关</td></tr><tr><td>Kimi Work Goal Mode</td><td>Work 帮助</td><td>不是网页聊天的同一份文档</td></tr><tr><td>Kimi Code <code>/goal</code></td><td>Code CLI</td><td><strong>不是</strong> kimi.com 输入框命令</td></tr></tbody></table><p>没有独立的「Goal 产品」一级入口。家族图里只占一行。</p><h2 id="两份-projects" tabindex="-1">两份 Projects <a class="header-anchor" href="#两份-projects" aria-label="Permalink to &quot;两份 Projects&quot;">​</a></h2><p>官方原文（<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>）：Kimi Work desktop app 也有 Projects，<strong>与 Kimi (Chat) projects 不相连、不共享数据</strong>。</p><table tabindex="0"><thead><tr><th></th><th>kimi.com Projects</th><th>Kimi Work Projects</th></tr></thead><tbody><tr><td><strong>干什么</strong></td><td>网页工作台的持久工作区</td><td>桌面端任务空间</td></tr><tr><td><strong>本目录</strong></td><td>Tutorial / Cookbook</td><td>地图一行，不写步骤</td></tr></tbody></table><h2 id="额度、记忆、skills、插件" tabindex="-1">额度、记忆、Skills、插件 <a class="header-anchor" href="#额度、记忆、skills、插件" aria-label="Permalink to &quot;额度、记忆、Skills、插件&quot;">​</a></h2><p><strong>额度池：</strong> 会员功能共用水池，按 token 计。聊天 K2.6 单独免费。Kimi Code 另有 5 小时 / 每周速率限制。不要把「Agent 额度 60」理解成「只能聊 60 句」——官方脚注写那是按典型任务折算的近似值。</p><p><strong>两套套餐名：</strong> 会员页 Moderato / Allegretto / Allegro / Vivace（美元）。Projects / Scheduled Tasks 页 Free / Go / Pro / Max / Ultra。以各自页面为准，禁止合并成一张「应该是」。</p><p><strong>记忆：</strong> 跨会话偏好。官方：不用于训练；不主动记未授权隐私。项目上下文会注入「全局主记忆」，但项目指令只在该项目生效。</p><p><strong>Skills：</strong> 按需加载的知识包。官方 / 推荐 / 开源 / 自定义。键入 <code>/</code>。</p><p><strong>插件：</strong> 接第三方。K3 / K3 Swarm 和部分场景可用；Claw、Plus 对话不行。和 Kimi Code 的插件系统不是同一套配置。</p><p><strong>定时任务：</strong> kimi.com 云端跑；Kimi Work 还可本地跑（应用得开着）。</p><h2 id="禁止写进正文的说法" tabindex="-1">禁止写进正文的说法 <a class="header-anchor" href="#禁止写进正文的说法" aria-label="Permalink to &quot;禁止写进正文的说法&quot;">​</a></h2><ul><li>「Kimi 就是 Kimi Code」</li><li>「网页输入 <code>/goal</code> 等于 CLI Goal」</li><li>「Moderato 就是 Go」</li><li>「Claw 群聊 = Agent Swarm」</li><li>把 Code 安装脚本当本目录 Quickstart</li><li>人民币价（本调研未打开独立中文标价页当唯一真源）</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./kimi.html">教程</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-cheatsheet.html">速查表</a></li></ul>',25)])])}const f=r(d,[["render",i]]);export{b as __pageData,f as default};
